  function fastestHour(stops){let best=0,start=null;for(let i=0;i<stops.length;i++){let j=i;while(j+1<stops.length&&stops[j+1].timestamp-stops[i].timestamp<=3600000)j++;if(j-i+1>best){best=j-i+1;start=stops[i].timestamp;}}return{count:best,start};}
  function showReport(id){const saved=routes().find(r=>r.id===id);if(!saved)return;const ms=activeMs(saved,saved.endedAt||Date.now()),overall=saved.stops.length?pace(ms/saved.stops.length):0,locations=routeLocations(saved),multi=saved.stops.filter(s=>stopLocations(s)>1).length,fast=fastestHour(saved.stops),zones=buildZones([saved]),top=zones[0],totes=toteSegments([saved]),breakMs=pausedMs(saved,saved.endedAt||Date.now()),delta=saved.paceGoal?overall-saved.paceGoal:null,auto=saved.stops.filter(s=>s.source==='auto').length,load=workloadScore(saved),comparison=comparisonFor(saved);
    $('#reportDate').textContent=dateLabel(saved.startedAt);$('#reportPace').textContent=overall?overall.toFixed(1):'—';$('#reportGoal').textContent=delta==null?'Route complete':`${Math.abs(delta).toFixed(1)}/hr ${delta>=0?'above':'below'} goal`;
    $('#reportMetrics').innerHTML=`<div class="report-metric"><span>STOPS / LOC.</span><b>${saved.stops.length} / ${locations}</b></div><div class="report-metric"><span>ACTIVE TIME</span><b>${formatDuration(ms).slice(0,5)}</b></div><div class="report-metric"><span>TOTES</span><b>${totes.length}</b></div><div class="report-metric"><span>BREAK TIME</span><b>${formatDuration(breakMs).slice(0,5)}</b></div>`;
    $('#reportHighlights').innerHTML=`<div class="report-highlight"><span>Route Load Index</span><b>${load.score} · ${load.label}</b></div><div class="report-highlight"><span>Similar-route pace</span><b>${comparison?`${comparison.paceDelta>=0?'+':''}${comparison.paceDelta.toFixed(1)}/hr vs ${comparison.count}`:'More routes needed'}</b></div><div class="report-highlight"><span>Fastest rolling hour</span><b>${fast.count?`${fast.count} stops · ${timeLabel(fast.start)}`:'—'}</b></div><div class="report-highlight"><span>Multi-location stops</span><b>${multi} stops · ${locations} total locations</b></div><div class="report-highlight"><span>Recorded street distance</span><b>${formatDistance(trackDistance(saved))}</b></div><div class="report-highlight"><span>Most active area</span><b>${top?`${top.name} · ${top.count} stops / ${top.locations} locations`:'—'}</b></div><div class="report-highlight"><span>Automatic detections</span><b>${auto} of ${saved.stops.length}</b></div><div class="report-highlight"><span>Average stops / locations per tote</span><b>${totes.length?`${(totes.reduce((n,t)=>n+t.stops,0)/totes.length).toFixed(1)} / ${(totes.reduce((n,t)=>n+t.locations,0)/totes.length).toFixed(1)}`:'—'}</b></div>`;
    reportText=`RouteHeat · ${dateLabel(saved.startedAt)}\n${saved.stops.length} stops · ${locations} delivery locations · ${overall?overall.toFixed(1):'—'} stops/hr · load ${load.score} (${load.label}) · ${formatDuration(ms).slice(0,5)} active time · ${totes.length} totes${delta==null?'':` · ${Math.abs(delta).toFixed(1)}/hr ${delta>=0?'above':'below'} goal`}`;
    $('#reportModal').classList.add('open');$('#reportModal').setAttribute('aria-hidden','false');setTimeout(()=>{if(reportMap){reportMap.remove();reportMap=null;}reportMap=L.map('reportMap',{zoomControl:false,attributionControl:true,dragging:false,scrollWheelZoom:false,doubleClickZoom:false});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(reportMap);const layer=L.layerGroup().addTo(reportMap);routeEvents(saved).forEach(e=>drawSavedEvent(saved,e,layer));fitSavedRoute(saved,reportMap);},60);
  }
  function closeReport(){if(reportMap){reportMap.remove();reportMap=null;}$('#reportModal').classList.remove('open');$('#reportModal').setAttribute('aria-hidden','true');}
  async function shareReport(){try{if(navigator.share)await navigator.share({title:'RouteHeat route report',text:reportText});else{await navigator.clipboard.writeText(reportText);toast('Route summary copied');}}catch(error){if(error?.name!=='AbortError')toast('Could not share summary');}}
  function exportCsv(items){
    const rows=[['route_id','route_date','route_started','route_ended','event_type','event_number','stop_source','location_count','event_time','segment_seconds','segment_stops_per_hour','latitude','longitude','gps_accuracy_m','after_stop']];
    items.forEach(r=>{r.stops.forEach(s=>rows.push([r.id,new Date(r.startedAt).toLocaleDateString(),new Date(r.startedAt).toISOString(),new Date(r.endedAt).toISOString(),'stop',s.number,s.source||'manual',stopLocations(s),new Date(s.timestamp).toISOString(),Math.round(s.segmentMs/1000),pace(s.segmentMs).toFixed(2),s.lat??'',s.lng??'',s.accuracy?Math.round(s.accuracy):'','']));(r.totes||[]).forEach(t=>rows.push([r.id,new Date(r.startedAt).toLocaleDateString(),new Date(r.startedAt).toISOString(),new Date(r.endedAt).toISOString(),'new_tote',t.number,'','',new Date(t.timestamp).toISOString(),'','',t.lat??'',t.lng??'',t.accuracy?Math.round(t.accuracy):'',t.afterStop]));(r.track||[]).forEach((raw,i)=>{const p=trackPoint(raw);rows.push([r.id,new Date(r.startedAt).toLocaleDateString(),new Date(r.startedAt).toISOString(),new Date(r.endedAt).toISOString(),'track_point',i+1,'','',new Date(p.timestamp).toISOString(),'','',p.lat,p.lng,'','']);});});
    const csv=rows.map(row=>row.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\r\n'),filename=`routeheat-${new Date().toISOString().slice(0,10)}.csv`;if(window.RouteHeatAndroid?.saveCsv){window.RouteHeatAndroid.saveCsv(csv,filename);toast('Choose where to save the CSV');return;}const blob=new Blob([csv],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();URL.revokeObjectURL(a.href);toast('CSV export ready');
  }

